#define MAX_STEPS 100
#define MAX_DIST 100.0
#define SURF_DIST 0.001

// Custom gradient - https://iquilezles.org/articles/palettes/
vec3 palette(float t) {
    return .5+.5*cos(6.28318*(t+vec3(.3,.416,.557)));
}
// Sphere Signed Distance Function
float sphereSDF(vec3 p, float radius) {
    return length(p) - radius;
}

// Torus Signed Distance Function (3D Ring)
float torusSDF(vec3 p, vec2 t) {
    vec2 q = vec2(length(p.xz) - t.x, p.y);
    return length(q) - t.y;
}

// Rotate a vector around the Z-axis
vec3 rotateZ(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(c * p.x - s * p.y, s * p.x + c * p.y, p.z);
}

// Rotate a vector around the Y-axis
vec3 rotateY(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}

// Rotate a vector around the X-axis
vec3 rotateX(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}

// Smooth Minimum Function
float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// Domain Repetition Function with Boundary Fix
vec3 repeat(vec3 p, vec3 c, out vec3 gridID) {
    gridID = floor((p + 0.5 * c) / c); // Calculate gridID
    vec3 repeatedP = mod(p + 0.5 * c, c) - 0.5 * c;
    return clamp(repeatedP, -0.5 * c + 0.001, 0.5 * c - 0.001); // Prevent boundary overlap
}

// Scene Signed Distance Function
float sceneSDF(vec3 p) {
    // Domain repetition
    vec3 cellSize = vec3(9.0, 9.0, 9.0); // Repetition size in all axes
    vec3 gridID;
    p = repeat(p, cellSize, gridID);
    // Calculate rotation speed based on distance from the center of the grid
    float gridDistance = length(gridID);
    float rotationSpeed = gridDistance * radians(20.0); // Adjust the multiplier for effect

    // Apply transformations to the scene
    vec3 rotatedP = rotateX(p, radians(15.*gridDistance)*(iTime));

    vec3 sphereP = vec3(rotatedP - vec3(0, 0, 0));
    sphereP = rotateY(sphereP, radians(45.0) * rotationSpeed * iTime); // Animate sphere rotation
    vec3 sphereP2 = rotateY(sphereP, -radians(90.0) * rotationSpeed * iTime); // Animate sphere rotation

    // Offset the sphere and torus
    float sphere = sphereSDF(sphereP - vec3(0.0, 0.0, 2.0), 0.333); // Sphere radius 0.333
    float sphere2 = sphereSDF(sphereP2 - vec3(0.0, 0.0, -2.0), 0.333); // Sphere radius 0.333
    float torus = torusSDF(rotatedP - vec3(0.0, 0.0, 0.0), vec2(2.0, 50.*3./iResolution.y)); // Thinner torus
    // Add a small margin to prevent overlap flickering
    float spheres = smin(sphere, sphere2, 0.5 + 0.1);
    return smin(spheres, torus, 0.25 + 0.1); // Union of the two shapes with margin
}

// Raymarching function
float rayMarch(vec3 ro, vec3 rd) {
    float dist = 0.0;
    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + dist * rd;
        float d = sceneSDF(p);
        if (d < max(SURF_DIST, 0.0001)) { // Avoid too small steps
            return dist;
        }
        if (dist > MAX_DIST) {
            break;
        }
        dist += d;
    }
    return MAX_DIST;
}

// Normal calculation using numerical gradient
vec3 getNormal(vec3 p) {
    float d = sceneSDF(p);
    vec2 e = vec2(0.001, 0.0);
    vec3 n = d - vec3(
        sceneSDF(p - e.xyy),
        sceneSDF(p - e.yxy),
        sceneSDF(p - e.yyx)
    );
    return normalize(n);
}

// Basic lighting with dynamic light rotation
float lighting(vec3 p, vec3 lightPos, float time) {
    vec3 n = getNormal(p);

    // Rotate light direction to match scene rotation
    vec3 lightDir = rotateY(normalize(lightPos - p), radians(10.0));
    return max(dot(n, lightDir), 0.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalized pixel coordinates (from -1 to 1)
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y;

    // Camera origin and ray direction
    vec3 ro = vec3(0.0, 0.0, -5.0); // Camera position
    vec3 rd = normalize(vec3(uv, -1.0)); // Ray direction
    //rd*=rotateX(rd, radians(90.)*(iTime*.5));

    // Rotate the ray direction around the X-axis
    float angle = radians(0.0); // Currently no additional rotation on the X-axis

    // Perform raymarching
    float dist = rayMarch(ro, rd);
    vec3 p = ro + dist * rd;

    // Shade the shapes if the ray hits them
    float intensity = -.125;
    if (dist < MAX_DIST) {
        intensity = lighting(p, vec3(5.0, 2.0, 3.0), iTime); // Light position and animation
    }

    // Final color
    vec3 color = vec3(intensity)*palette((intensity)+.5);
    fragColor = vec4(color, 1.0);
}
